/* Lightweight CPU 3D renderer for devices without WebGL. */
window.darnaSoftwareStudio=function(box){
const canvas=document.createElement('canvas');canvas.tabIndex=0;canvas.setAttribute('role','img');canvas.setAttribute('aria-label','Tajine 3D interactif : glissez pour tourner, flèches pour incliner');box.append(canvas);box.querySelector('#tjimg').style.display='none';box.querySelector('#tjgo').hidden=true;const ctx=canvas.getContext('2d');let width,height,az=.4,tilt=.31,zoom=1,drag=null,visible=false,frame=null,amount=0,finish='green';
const colors={green:[31,87,68],clay:[164,83,52],ivory:[221,213,190]};const brass=[183,151,89];
const meshes=[];function lathe(profile,color,part='base',segments=72,pattern=false){const verts=[];for(let i=0;i<profile.length;i++){const[r,y]=profile[i];for(let j=0;j<segments;j++){const a=j/segments*Math.PI*2;verts.push([r*Math.cos(a),y,r*Math.sin(a)])}}for(let i=0;i<profile.length-1;i++)for(let j=0;j<segments;j++){const k=(j+1)%segments;meshes.push({v:[verts[i*segments+j],verts[i*segments+k],verts[(i+1)*segments+k],verts[(i+1)*segments+j]],color,part,pattern:pattern&&j%6===0})}}
lathe([[0,-.14],[1.6,-.14],[2.23,-.04],[2.3,0],[2.26,.04],[1.7,-.07],[0,-.07]],[47,54,43]);
lathe([[0,0],[1.2,0],[1.55,.09],[1.77,.24],[1.85,.43],[1.84,.55],[1.73,.54],[1.61,.31],[0,.23]],'glaze');
lathe([[1.83,.49],[1.86,.5],[1.86,.53],[1.83,.54]],brass);
lathe([[1.78,0],[1.84,.06],[1.8,.13],[1.65,.27],[1.4,.54],[1.15,.84],[.9,1.13],[.65,1.43],[.4,1.72],[.21,1.93],[.12,1.94],[.16,1.77],[.38,1.57],[.6,1.3],[.86,1],[1.12,.72],[1.4,.42],[1.73,.09]],'glaze','lid',96,true);
lathe([[1.8,.08],[1.82,.10],[1.8,.13]],brass,'lid',96);lathe([[.4,1.69],[.42,1.70],[.4,1.72]],brass,'lid');
lathe([[0,1.91],[.16,1.91],[.22,1.96],[.23,2.08],[.31,2.11],[.31,2.17],[.24,2.2],[.13,2.21],[0,2.21]],brass,'lid');
lathe([[0,.36],[1.62,.36],[1.62,.39],[0,.39]],[147,104,36],'food');
// Faceted olive and chicken shapes, all use the same 3D projection.
function ellipsoid(x,y,z,rx,ry,rz,color){const profile=[];const before=meshes.length;for(let i=0;i<=8;i++){const a=-Math.PI/2+i/8*Math.PI;profile.push([Math.cos(a),Math.sin(a)])}lathe(profile,color,'food',16);for(let i=before;i<meshes.length;i++)meshes[i].v=meshes[i].v.map(p=>[x+p[0]*rx,y+p[1]*ry,z+p[2]*rz])}
for(let i=0;i<7;i++){const a=i/7*Math.PI*2;ellipsoid(Math.cos(a)*.8,.48,Math.sin(a)*.8,.4,.16,.33,[184+i%3*9,127+i%2*15,54])}for(let i=0;i<15;i++){const a=i/15*Math.PI*2;ellipsoid(Math.cos(a)*1.3,.45,Math.sin(a)*1.3,.08,.07,.13,[95,104,43])}
function transform(p,part){let[x,y,z]=p;if(part==='lid'){y+=.56+amount*1.6;x+=amount*.15}y-=1.2;const x2=x*Math.cos(az)+z*Math.sin(az),z2=-x*Math.sin(az)+z*Math.cos(az);return[x2,y*Math.cos(tilt)-z2*Math.sin(tilt),y*Math.sin(tilt)+z2*Math.cos(tilt)]}
function draw(){frame=null;if(!visible||document.hidden)return;const stopped=reduce||document.documentElement.classList.contains("motion-paused"),target=lid?1:0;amount=stopped?target:amount+(target-amount)*.09;if(!stopped&&!drag)az+=.003;ctx.clearRect(0,0,width,height);const scale=width/5.9*zoom,cy=height*.62;const shadow=ctx.createRadialGradient(width/2,height*.82,0,width/2,height*.82,width*.37);shadow.addColorStop(0,'#0008');shadow.addColorStop(1,'#0000');ctx.fillStyle=shadow;ctx.save();ctx.translate(0,height*.55);ctx.scale(1,.34);ctx.fillRect(0,0,width,height);ctx.restore();
const projected=meshes.map(m=>{const v=m.v.map(p=>transform(p,m.part));return{m,v,depth:v.reduce((a,p)=>a+p[2],0)/4}}).sort((a,b)=>a.depth-b.depth);
for(const{m,v}of projected){const u=v[1].map((n,i)=>n-v[0][i]),w=v[3].map((n,i)=>n-v[0][i]);let nx=u[1]*w[2]-u[2]*w[1],ny=u[2]*w[0]-u[0]*w[2],nz=u[0]*w[1]-u[1]*w[0];const length=Math.hypot(nx,ny,nz)||1;nx/=length;ny/=length;nz/=length;const light=Math.max(0,-nx*.4+ny*.65+nz*.65);const highlight=Math.pow(Math.max(0,-nx*.45+ny*.3+nz*.84),finish==='clay'?16:44);const color=m.pattern?brass:m.color==='glaze'?colors[finish]:m.color;const shade=.48+light*.65;const rgb=color.map(c=>Math.min(255,Math.round(c*shade+highlight*(finish==='clay'?22:105))));ctx.fillStyle=`rgb(${rgb})`;ctx.beginPath();v.forEach(([x,y,z],i)=>{const persp=8/(8-z*.15);const px=width/2+x*scale*persp,py=cy-y*scale*persp;i?ctx.lineTo(px,py):ctx.moveTo(px,py)});ctx.closePath();ctx.fill();ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=.45;ctx.stroke()}
if(!stopped||Math.abs(amount-target)>.002)render()}
function render(){if(!frame)frame=requestAnimationFrame(draw)}function resize(){width=box.clientWidth;height=box.clientHeight;const d=Math.min(devicePixelRatio,1.5);canvas.width=width*d;canvas.height=height*d;ctx.setTransform(d,0,0,d,0,0);render()}new ResizeObserver(resize).observe(box);new IntersectionObserver(e=>{visible=e[0].isIntersecting;if(visible)render()}).observe(box);document.addEventListener('visibilitychange',()=>{if(!document.hidden)render()});
canvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,az,tilt};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag)return;az=drag.az+(e.clientX-drag.x)*.01;tilt=Math.max(.05,Math.min(.8,drag.tilt+(e.clientY-drag.y)*.004));render()});for(const event of ['pointerup','pointercancel'])canvas.addEventListener(event,()=>{drag=null;render()});canvas.addEventListener('wheel',e=>{if(!canvas.matches(':focus'))return;e.preventDefault();zoom=Math.max(.8,Math.min(1.2,zoom-e.deltaY*.001));render()},{passive:false});canvas.addEventListener('keydown',e=>{if(!e.key.startsWith('Arrow'))return;e.preventDefault();if(e.key==='ArrowLeft')az-=.15;if(e.key==='ArrowRight')az+=.15;if(e.key==='ArrowUp')tilt=Math.min(.8,tilt+.08);if(e.key==='ArrowDown')tilt=Math.max(.05,tilt-.08);render()});document.addEventListener("darna-motion-change",render);resize();return{render,setFinish(f){finish=f;render()},reset(){az=.4;tilt=.31;zoom=1;lid=false;document.querySelector('#tjlid').textContent=T[L].tj_btn;render()}};
};
